import { mkdir } from 'node:fs/promises';
import { chromium } from 'playwright';
const base=process.env.JOURNAL_BASE_URL||'http://127.0.0.1:4173',IMG='https://storage.googleapis.com/mediapipe-assets/portrait.jpg';
const expect=(x,m)=>{if(!x)throw Error(m)};
await mkdir('.artifacts/vision-f6',{recursive:true});
const browser=await chromium.launch({headless:true});
const context=await browser.newContext({viewport:{width:390,height:844},deviceScaleFactor:3,userAgent:'Mozilla/5.0 (Linux; Android 16; SM-S931N) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/151.0.0.0 Mobile Safari/537.36'});
const page=await context.newPage(),errors=[];page.on('pageerror',e=>errors.push(e.message));
await page.goto(`${base}/#/lab/vision`,{waitUntil:'domcontentloaded'});
await page.waitForFunction(()=>window.HJVisionF6&&document.querySelector('[data-vision-lab]')?.dataset.f6Bound,{timeout:15000});
const boot=await page.evaluate(()=>({version:window.HJVisionF6.version,mode:window.HJVisionF6.sources.mode,watermark:document.querySelector('.vision-stage-watermark-v11 span')?.textContent,videoOpacity:Number(getComputedStyle(document.querySelector('[data-vision-video]')).opacity),canvasDisplay:getComputedStyle(document.querySelector('[data-vision-overlay]')).display}));
expect(boot.version==='F6-20260830-2106',`F6 revision drift: ${JSON.stringify(boot)}`);
expect(boot.mode==='direct-display-manual-mesh',`F6 mode drift: ${JSON.stringify(boot)}`);
expect(boot.watermark?.includes('F6'),`F6 watermark missing: ${JSON.stringify(boot)}`);
expect(boot.videoOpacity===0&&boot.canvasDisplay!=='none',`F6 must present the camera and mesh through the visible canvas: ${JSON.stringify(boot)}`);
const source=await page.evaluate(()=>fetch('./journal-v12-vision-f5.js',{cache:'no-store'}).then(r=>r.text()));
expect(source.includes('function visibleFace(')&&source.includes('function project('), 'F6 must project normalized landmarks into the final display canvas');
expect(source.includes('Deliberately manual')&&!source.includes('drawer.drawConnectors'), 'F6 physical-device path must not depend on DrawingUtils rendering');
expect(source.includes("metric('backend','F6 · direct-display')"), 'F6 backend telemetry missing');
const started=await page.evaluate(async IMG=>{const r=await fetch(IMG,{cache:'no-store'});if(!r.ok)throw Error(`portrait ${r.status}`);const bmp=await createImageBitmap(await r.blob()),c=document.createElement('canvas');c.width=480;c.height=640;const x=c.getContext('2d');let phase=0;const paint=()=>{phase+=.19;x.fillStyle='#07090d';x.fillRect(0,0,c.width,c.height);const z=Math.max(c.width/bmp.width,c.height/bmp.height)*1.1,w=bmp.width*z,h=bmp.height*z,dx=(c.width-w)/2+Math.sin(phase)*20,dy=(c.height-h)/2;x.drawImage(bmp,dx,dy,w,h)};paint();const s=c.captureStream(24),timer=setInterval(paint,1000/24);window.__f6fixture={bmp,s,timer};return window.HJVisionF6.startStreamForTest(s)},IMG);
expect(started,'F6 stream did not start');
await page.waitForFunction(()=>{const s=window.HJVisionF6?.stats?.();return s?.faceRuns>=5&&s?.facePoints>400&&s?.meshEdges>2000&&s?.meshDrawCalls>=3},{timeout:15000});
const samples=[];for(let i=0;i<6;i++){await page.waitForTimeout(180);samples.push(await page.evaluate(()=>window.HJVisionF6.stats()))}
const last=samples.at(-1),centers=samples.map(s=>s.faceCenterX).filter(Number.isFinite),travel=centers.length?Math.max(...centers)-Math.min(...centers):0;
expect(last.faceRuns>=8,`F6 FaceLandmarker did not repeat: ${JSON.stringify(samples)}`);
expect(last.facePoints>400,`F6 lost face landmarks: ${JSON.stringify(last)}`);
expect(last.meshEdges>2000,`F6 did not draw dense tessellation edges: ${JSON.stringify(last)}`);
expect(last.meshDrawCalls>=8,`F6 display mesh renderer did not repeat: ${JSON.stringify(last)}`);
expect(last.videoWidth>=360&&last.videoHeight>=360,`F6 video surface invalid: ${JSON.stringify(last)}`);
expect(last.meshBounds?.width>80&&last.meshBounds?.height>100,`F6 projected face bounds invalid: ${JSON.stringify(last)}`);
expect(travel>.006,`F6 face landmarks did not follow moving stream: ${JSON.stringify({travel,samples})}`);
const pixels=await page.evaluate(()=>{const c=document.querySelector('[data-vision-overlay]'),x=c.getContext('2d'),d=x.getImageData(0,0,c.width,c.height).data;let green=0,cyan=0,magenta=0,lit=0,total=0,minX=Infinity,minY=Infinity,maxX=-Infinity,maxY=-Infinity;const x0=Math.floor(c.width*.06),x1=Math.floor(c.width*.94),y0=Math.floor(c.height*.14),y1=Math.floor(c.height*.92);for(let y=y0;y<y1;y++)for(let xx=x0;xx<x1;xx++){let i=(y*c.width+xx)*4,r=d[i],g=d[i+1],b=d[i+2],a=d[i+3];total++;if(a>240&&(r+g+b)>120)lit++;if(a>220&&g>150&&g>r*1.35&&g>b*1.12){green++;if(xx<minX)minX=xx;if(xx>maxX)maxX=xx;if(y<minY)minY=y;if(y>maxY)maxY=y}if(a>220&&b>160&&g>130&&b>r*1.25)cyan++;if(a>220&&r>170&&b>110&&r>g*1.35)magenta++}return{w:c.width,h:c.height,green,cyan,magenta,lit,total,greenBounds:Number.isFinite(minX)?{minX,minY,maxX,maxY,width:maxX-minX,height:maxY-minY}:null,faceState:document.querySelector('[data-face-state]')?.textContent,backend:document.querySelector('[data-vm="backend"] strong')?.textContent}});
expect(pixels.lit>pixels.total*.35,`F6 camera pixels are not present in the visible canvas: ${JSON.stringify(pixels)}`);
expect(pixels.green>2500,`F6 direct display face tessellation is not visibly present: ${JSON.stringify(pixels)}`);
expect(pixels.greenBounds?.width>100&&pixels.greenBounds?.height>120,`F6 green mesh does not span a face-sized region: ${JSON.stringify(pixels)}`);
expect(pixels.cyan>100&&pixels.magenta>50,`F6 eye/lip feature colors are not visibly present: ${JSON.stringify(pixels)}`);
expect(pixels.faceState?.includes('478')&&pixels.faceState?.includes('EDGES'),`F6 face state missing edge proof: ${JSON.stringify(pixels)}`);
expect(pixels.backend?.includes('F6'),`F6 backend HUD missing: ${JSON.stringify(pixels)}`);
await page.locator('.vision-camera-card-v11').screenshot({path:'.artifacts/vision-f6/vision-f6-realtime.png'});
await page.evaluate(()=>{const f=window.__f6fixture;if(f){clearInterval(f.timer);f.s.getTracks().forEach(t=>t.stop());f.bmp.close?.();delete window.__f6fixture}window.HJVisionF6.stop()});
expect(errors.length===0,`F6 page errors: ${errors.join(' | ')}`);
console.log(`Vision F6 direct-display realtime ok: ${JSON.stringify({last,travel,pixels})}`);
await context.close();await browser.close();